import { useState } from 'react';
import { motion } from 'framer-motion';
import { Repeat, Plus, CheckCircle2, Clock, TrendingUp, History } from 'lucide-react';
import { PageHeader } from '@/components/common/page-header';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ScrollArea } from '@/components/ui/scroll-area';
import { cn, formatDate } from '@/lib/utils';
import { mockRevisions } from '@/lib/mock-data';
import type { RevisionItem } from '@/types';
import { toast } from 'sonner';

export default function RevisionPage() {
  const [revisions, setRevisions] = useState(mockRevisions);
  const [tab, setTab] = useState<'upcoming' | 'completed' | 'all'>('upcoming');

  const upcoming = revisions.filter((r) => !r.completed).sort((a, b) => new Date(a.scheduledDate).getTime() - new Date(b.scheduledDate).getTime());
  const completed = revisions.filter((r) => r.completed);
  const display = tab === 'upcoming' ? upcoming : tab === 'completed' ? completed : revisions;

  const markComplete = (id: string) => {
    setRevisions((prev) => prev.map((r) => r.id === id ? { ...r, completed: true, progress: 100 } : r));
    toast.success('Revision marked complete');
  };

  return (
    <div className="space-y-6">
      <PageHeader
        title="Revision Planner"
        description="Spaced repetition schedules to reinforce your learning"
        icon={Repeat}
        actions={<Button className="gap-2" onClick={() => toast.info('New revision form will open here')}><Plus className="h-4 w-4" /> New Revision</Button>}
      />

      {/* Stats */}
      <div className="grid gap-4 sm:grid-cols-3">
        <Card className="p-5">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary/10 text-primary"><Clock className="h-5 w-5" /></div>
            <div><p className="text-2xl font-semibold">{upcoming.length}</p><p className="text-sm text-muted-foreground">Upcoming</p></div>
          </div>
        </Card>
        <Card className="p-5">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-success/10 text-success"><CheckCircle2 className="h-5 w-5" /></div>
            <div><p className="text-2xl font-semibold">{completed.length}</p><p className="text-sm text-muted-foreground">Completed</p></div>
          </div>
        </Card>
        <Card className="p-5">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-accent/10 text-accent"><TrendingUp className="h-5 w-5" /></div>
            <div><p className="text-2xl font-semibold">{Math.round((completed.length / revisions.length) * 100)}%</p><p className="text-sm text-muted-foreground">Overall Progress</p></div>
          </div>
        </Card>
      </div>

      <Tabs value={tab} onValueChange={(v) => setTab(v as 'upcoming' | 'completed' | 'all')}>
        <TabsList>
          <TabsTrigger value="upcoming">Upcoming</TabsTrigger>
          <TabsTrigger value="completed">Completed</TabsTrigger>
          <TabsTrigger value="all">All</TabsTrigger>
        </TabsList>
      </Tabs>

      {/* Timeline */}
      <Card className="p-5">
        <CardHeader className="mb-4 flex flex-row items-center justify-between space-y-0 p-0">
          <CardTitle className="text-base font-medium">Revision Timeline</CardTitle>
          <History className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent className="p-0">
          {display.length === 0 ? (
            <p className="py-8 text-center text-sm text-muted-foreground">No revisions in this view</p>
          ) : (
            <div className="relative space-y-4 before:absolute before:left-[15px] before:top-2 before:h-[calc(100%-1rem)] before:w-px before:bg-border">
              {display.map((r, i) => (
                <RevisionTimelineItem key={r.id} item={r} delay={i * 0.05} onComplete={() => markComplete(r.id)} />
              ))}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function RevisionTimelineItem({ item, delay, onComplete }: { item: RevisionItem; delay: number; onComplete: () => void }) {
  return (
    <motion.div initial={{ opacity: 0, x: -8 }} animate={{ opacity: 1, x: 0 }} transition={{ delay }} className="relative flex gap-4 pl-2">
      <div className={cn('relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2', item.completed ? 'border-success bg-success/10 text-success' : 'border-primary bg-card text-primary')}>
        {item.completed ? <CheckCircle2 className="h-4 w-4" /> : <Repeat className="h-4 w-4" />}
      </div>
      <div className="flex-1 rounded-lg border border-border/50 p-3.5">
        <div className="flex items-start justify-between gap-2">
          <div>
            <p className={cn('text-sm font-medium', item.completed && 'text-muted-foreground line-through')}>{item.title}</p>
            <div className="mt-1 flex items-center gap-2">
              <Badge variant="outline" className="text-2xs">{item.subject}</Badge>
              <span className="text-2xs text-muted-foreground">Due {formatDate(item.scheduledDate)}</span>
              <span className="text-2xs text-muted-foreground">Interval: {item.interval}d</span>
            </div>
          </div>
          {!item.completed && <Button size="sm" variant="outline" onClick={onComplete}>Mark done</Button>}
        </div>
        <div className="mt-2.5 flex items-center gap-2">
          <Progress value={item.progress} className="h-1.5" />
          <span className="text-2xs text-muted-foreground">{item.progress}%</span>
        </div>
      </div>
    </motion.div>
  );
}
